#abstract class 
#Gemini class will inherit the methods here... 
from abc import ABC, abstractmethod                                                                                                                                                                                                                                                                  
from typing import Optional                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
class LLMService(ABC):                                                                                                                                                                                                                                                                               
    """                                                                                                                                                                                                                                                                                              
    Abstract interface for LLM services.                                                                                                                                                                                                                                                             
    Any AI provider (Gemini, Mock for tests, etc.) must implement this contract.                                                                                                                                                                                                                     
    """                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                         
    @abstractmethod                                                                                                                                                                                                                                                                                  
    def generate(self, prompt: str, system_instruction: Optional[str] = None) -> str:                                                                                                                                                                                                                
        """                                                                                                                                                                                                                                                                                          
        Sends a prompt to the LLM and returns the raw text response.
        :param prompt: The handover text or user input.                                                                                                                                                                                                                                              
        :param system_instruction: Optional instructions defining the AI role and output format.                                                                                                                                                                                                     
        :return: Raw text response from the model.                                                                                                                                                                                                                                                   
        """                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                  
        pass  